ejemplo.es:
def binaria(lista, objetivo):
    inicio, fin = 0, len(lista) - 1
    while inicio <= fin:
        medio = (inicio + fin) // 2
        if lista[medio] == objetivo:
            return medio
        if lista[medio] < objetivo:
            inicio = medio + 1
        else:
            fin = medio - 1
    return -1

print(binaria([1, 3, 5, 7, 9, 11], 7))

ejemplo.en:
def binary(items, target):
    start, end = 0, len(items) - 1
    while start <= end:
        middle = (start + end) // 2
        if items[middle] == target:
            return middle
        if items[middle] < target:
            start = middle + 1
        else:
            end = middle - 1
    return -1

print(binary([1, 3, 5, 7, 9, 11], 7))

